import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import base64
import io
from jinja2 import Template
import datetime
import warnings
warnings.filterwarnings('ignore')

def get_base64_plot(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    buf.seek(0)
    img_b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return img_b64

def generate_report():
    print("Loading data...")
    df = pd.read_csv('/app/benchmark/data.csv')
    df['date'] = pd.to_datetime(df['date'])
    df['year'] = df['date'].dt.year

    # Ensure numeric types
    for col in ['petrol_usd_liter', 'diesel_usd_liter', 'lpg_usd_liter', 'brent_crude_usd', 'tax_percentage']:
        df[col] = pd.to_numeric(df[col], errors='coerce')

    print("Calculating Global Overview...")
    global_stats = {
        'avg_petrol': df['petrol_usd_liter'].mean(),
        'range_petrol': (df['petrol_usd_liter'].min(), df['petrol_usd_liter'].max()),
        'avg_diesel': df['diesel_usd_liter'].mean(),
        'range_diesel': (df['diesel_usd_liter'].min(), df['diesel_usd_liter'].max()),
        'avg_lpg': df['lpg_usd_liter'].mean(),
        'range_lpg': (df['lpg_usd_liter'].min(), df['lpg_usd_liter'].max()),
        'avg_brent': df['brent_crude_usd'].mean()
    }

    print("Calculating Temporal Trends...")
    # KPI: Brent-to-Retail Correlation
    brent_petrol_corr = df['petrol_usd_liter'].corr(df['brent_crude_usd'])
    brent_diesel_corr = df['diesel_usd_liter'].corr(df['brent_crude_usd'])

    fig, ax1 = plt.subplots(figsize=(10, 5))
    ax2 = ax1.twinx()
    weekly_avg = df.groupby('date').agg({'petrol_usd_liter': 'mean', 'brent_crude_usd': 'mean'}).reset_index()
    ax1.plot(weekly_avg['date'], weekly_avg['petrol_usd_liter'], color='#2c3e50', linewidth=2, label='Global Avg Petrol Price')
    ax2.plot(weekly_avg['date'], weekly_avg['brent_crude_usd'], color='#c0392b', linestyle='--', linewidth=2, label='Brent Crude')
    ax1.set_xlabel('Date')
    ax1.set_ylabel('Retail Petrol (USD/Liter)', color='#2c3e50')
    ax2.set_ylabel('Brent Crude (USD/Barrel)', color='#c0392b')
    plt.title('Global Retail Petrol vs. Brent Crude Benchmark (2020–2026)', pad=20)
    fig.legend(loc="upper left", bbox_to_anchor=(0.1, 0.9))
    plt.grid(alpha=0.3)
    plot_temporal = get_base64_plot(fig)

    print("Calculating Regional Disparities...")
    region_yearly = df.groupby(['year', 'region'])['petrol_usd_liter'].mean().unstack()
    fig, ax = plt.subplots(figsize=(10, 6))
    region_yearly.plot(ax=ax, marker='o', linewidth=2)
    plt.title('Average Retail Petrol Price by Region (2020–2026)', pad=20)
    plt.ylabel('USD / Liter')
    plt.legend(title='Region', bbox_to_anchor=(1.05, 1), loc='upper left')
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plot_regional = get_base64_plot(fig)

    # KPI: Regional Price Spread
    def calculate_spread(group):
        avg_by_reg = group.groupby('region')['petrol_usd_liter'].mean()
        return avg_by_reg.max() - avg_by_reg.min()
    regional_spreads = df.groupby('year').apply(calculate_spread)

    # Create Spread DataFrame for table
    spread_df_html = pd.DataFrame({'Year': regional_spreads.index, 'Max Regional Spread (USD)': regional_spreads.values.round(3)}).to_html(index=False, classes='data-table')

    print("Calculating Subsidy Impact...")
    # KPI: Subsidy Price Dampening Effect
    sub_prices = df.groupby('subsidy_level')['petrol_usd_liter'].mean()
    high_sub = sub_prices.get('High', 0)
    low_sub = sub_prices.get('Low', 0)
    subsidy_dampening_effect = 0
    if low_sub > 0:
        subsidy_dampening_effect = ((low_sub - high_sub) / low_sub) * 100

    fig, ax = plt.subplots(figsize=(10, 5))
    subsidy_yearly = df.groupby(['year', 'subsidy_level'])['petrol_usd_liter'].mean().unstack()
    subsidy_yearly.plot(kind='bar', ax=ax, color=['#2980b9', '#e67e22'])
    plt.title('Average Petrol Prices: High vs. Low Subsidy Regimes', pad=20)
    plt.ylabel('USD / Liter')
    plt.xticks(rotation=0)
    plt.grid(axis='y', alpha=0.3)
    plot_subsidy = get_base64_plot(fig)

    print("Calculating Income Level Segmentation...")
    # KPI: Tax-to-Price Ratio by Income Level
    income_stats = df.groupby('income_level').agg({
        'petrol_usd_liter': 'mean',
        'tax_percentage': 'mean'
    }).reindex(['High', 'Middle', 'Low'])

    fig, ax1 = plt.subplots(figsize=(10, 5))
    ax2 = ax1.twinx()
    x = np.arange(len(income_stats.index))
    width = 0.4
    ax1.bar(x, income_stats['petrol_usd_liter'], width, color='#34495e', label='Avg Petrol Price')
    ax2.plot(x, income_stats['tax_percentage'], marker='D', color='#27ae60', markersize=8, linewidth=2, label='Avg Tax %')
    ax1.set_xticks(x)
    ax1.set_xticklabels(income_stats.index)
    ax1.set_ylabel('Price (USD/Liter)', color='#34495e')
    ax2.set_ylabel('Tax Percentage (%)', color='#27ae60')
    plt.title('Fuel Affordability & Taxation by Income Level', pad=20)
    fig.legend(loc="upper right", bbox_to_anchor=(0.9, 0.9))
    plt.grid(alpha=0.3)
    plot_income = get_base64_plot(fig)

    # Generate income table
    income_table_html = income_stats.round(2).reset_index().rename(columns={
        'income_level': 'Income Level',
        'petrol_usd_liter': 'Avg Petrol (USD/L)',
        'tax_percentage': 'Avg Tax (%)'
    }).to_html(index=False, classes='data-table')

    print("Generating HTML...")
    template_str = """
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
